/** SYNTHETIC generated presentation data for the canonical model viewer.
 *
 * Every value here is invented and generated by this file: no IFC file, GLB,
 * converter run, publisher output, household or native record exists behind
 * it. Digests are visibly patterned placeholders, not hashes of any bytes.
 * Coordinates are one renderer frame per floor (metres, +Y up); plan (x, z) is
 * that frame's ground plane. Only generated coverage declares a shared frame. */
import { PRESENTATION_KIND } from '../../src/lantern/canonical-ifc/model';
import type {
  ArtifactPin, CanonicalPresentation, CoordinateFacts, OverlayLayer, PlanFeature, PresentationMesh, PresentationRoom, PublicationPin,
} from '../../src/lantern/canonical-ifc/model';

type Rect = readonly [x0: number, z0: number, x1: number, z1: number];
const id = (block: string, n: number) => `00000000-0000-4000-8000-${block}${String(n).padStart(12 - block.length, '0')}`;
/** Visibly patterned placeholder digest; it identifies no bytes. */
const placeholderDigest = (n: number) => n.toString(16).padStart(2, '0').repeat(32);
/** Synthetic reviewed Atlas place link. */
const place = (n: number) => id('d1', n);

const BUILDING_A = id('c1', 1), BUILDING_COVERAGE = id('c2', 1);
const GROUND = id('c1f', 1), UPPER = id('c2f', 2), COVERAGE_GROUND = id('c2f', 1);
const SCOPE = { workspaceId: id('e1', 1), homeId: id('e2', 1) };

function box([x0, z0, x1, z1]: Rect, y0: number, y1: number): { positions: Float32Array; indices: Uint32Array } {
  const positions = new Float32Array([x0, y0, z0, x1, y0, z0, x1, y1, z0, x0, y1, z0, x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1]);
  // Outward counter-clockwise faces: -Z, +Z, -X, +X, -Y, +Y.
  const indices = new Uint32Array([0, 2, 1, 0, 3, 2, 4, 5, 6, 4, 6, 7, 0, 4, 7, 0, 7, 3, 1, 2, 6, 1, 6, 5, 0, 1, 5, 0, 5, 4, 3, 7, 6, 3, 6, 2]);
  return { positions, indices };
}
const ring = ([x0, z0, x1, z1]: Rect) => [[x0, z0], [x1, z0], [x1, z1], [x0, z1]] as const;

/** Axis-aligned wall run along x (z fixed) or z (x fixed). */
type Run = { readonly along: 'x' | 'z'; readonly at: number; readonly spans: readonly (readonly [number, number])[]; readonly t: number };
const wallRects = (runs: readonly Run[]): Rect[] => runs.flatMap(run => run.spans.map(([a, b]): Rect => run.along === 'x'
  ? [a - (a === 0 ? run.t / 2 : 0), run.at - run.t / 2, b + (b === 11 ? run.t / 2 : 0), run.at + run.t / 2]
  : [run.at - run.t / 2, a, run.at + run.t / 2, b]));

/** One floor occurrence of logical room `n`. Its occurrence token is opaque
 * text that stays the same across publications of the same room and floor. */
interface RoomSpec { readonly n: number; readonly label: string; readonly rect: Rect | null; readonly mesh: 'bound' | 'display-only' | 'none'; readonly ifc: string | null; readonly place: number | null }
interface FloorSpec { readonly floorId: string; readonly label: string; readonly short: string; readonly base: number; readonly rooms: readonly RoomSpec[]; readonly walls: readonly Run[]; readonly openings: readonly Rect[] }

const EXT = 0.25, INT = 0.1, FOOT: Rect = [0, 0, 11, 8.5];
const groundWalls: Run[] = [
  { along: 'x', at: 0, spans: [[0, 11]], t: EXT }, { along: 'x', at: 8.5, spans: [[0, 4.6], [5.6, 11]], t: EXT },
  { along: 'z', at: 0, spans: [[0, 8.5]], t: EXT }, { along: 'z', at: 11, spans: [[0, 8.5]], t: EXT },
  { along: 'x', at: 4.6, spans: [[0, 4.2], [5.2, 5.9], [6.6, 9.0], [10.0, 11]], t: INT },
  { along: 'z', at: 5.6, spans: [[0, 1.2], [2.4, 4.6]], t: INT },
  { along: 'z', at: 3.6, spans: [[4.6, 6.0], [6.9, 8.5]], t: INT },
  { along: 'z', at: 6.4, spans: [[4.6, 5.2], [5.9, 7.0], [7.7, 8.5]], t: INT },
  { along: 'x', at: 6.6, spans: [[6.4, 8.0]], t: INT },
  { along: 'z', at: 8.0, spans: [[4.6, 8.5]], t: INT },
];
const upperWalls: Run[] = [
  { along: 'x', at: 0, spans: [[0, 11]], t: EXT }, { along: 'x', at: 8.5, spans: [[0, 11]], t: EXT },
  { along: 'z', at: 0, spans: [[0, 8.5]], t: EXT }, { along: 'z', at: 11, spans: [[0, 8.5]], t: EXT },
  { along: 'x', at: 4.2, spans: [[0, 4.0], [4.8, 5.4], [6.2, 11]], t: INT },
  { along: 'z', at: 5.0, spans: [[0, 4.2]], t: INT },
  { along: 'z', at: 3.6, spans: [[4.2, 5.0], [5.8, 8.5]], t: INT },
  { along: 'z', at: 6.4, spans: [[4.2, 4.9], [5.7, 6.9], [7.6, 8.5]], t: INT },
  { along: 'x', at: 6.4, spans: [[6.4, 11]], t: INT },
];

const groundRooms = (kitchenLabel: string, withDining: boolean): RoomSpec[] => [
  { n: 1, label: 'Living room', rect: [0, 0, 5.6, 4.6], mesh: 'bound', ifc: '2Wq9SyntheticLiving01x', place: 1 },
  { n: 2, label: kitchenLabel, rect: [5.6, 0, 11, 4.6], mesh: 'bound', ifc: '2Wq9SyntheticKitchen1x', place: 2 },
  { n: 3, label: 'Stair hall', rect: [3.6, 4.6, 6.4, 8.5], mesh: 'bound', ifc: null, place: 3 },
  { n: 4, label: 'WC', rect: [6.4, 4.6, 8.0, 6.6], mesh: 'bound', ifc: null, place: null },
  { n: 5, label: 'Utility', rect: [6.4, 6.6, 8.0, 8.5], mesh: 'bound', ifc: null, place: 5 },
  { n: 6, label: 'Study', rect: [0, 4.6, 3.6, 8.5], mesh: 'bound', ifc: '2Wq9SyntheticStudy001x', place: 6 },
  withDining ? { n: 7, label: 'Dining room', rect: [8.0, 4.6, 11, 8.5], mesh: 'bound', ifc: null, place: 7 }
    : { n: 9, label: 'Garden room', rect: [8.0, 4.6, 11, 8.5], mesh: 'bound', ifc: null, place: null },
  // Plan-less occurrence: a known room on this floor with no drawn shape.
  { n: 8, label: 'Cellar', rect: null, mesh: 'none', ifc: null, place: null },
];

/** Opaque occurrence token: punctuation and spaces kept on purpose. */
const token = (block: string, n: number, short: string) => `synthetic space ${block}/${n} @ floor ${short}`;

function build(block: string, floors: readonly FloorSpec[], extraRooms: readonly PresentationRoom[]) {
  const rooms = new Map<number, { roomId: string; label: string; atlasPlaceId: string | null; occurrences: PresentationRoom['occurrences'][number][] }>();
  const meshes: PresentationMesh[] = [];
  const add = (floorId: string, occurrenceId: string | null, geometry: { positions: Float32Array; indices: Uint32Array }) =>
    meshes.push({ meshKey: `${floorId}/model.glb#${meshes.length}`, floorId, glbMeshIndex: meshes.length, occurrenceId, ...geometry });
  const presentationFloors = floors.map(floor => {
    const features: PlanFeature[] = [];
    add(floor.floorId, null, box([FOOT[0] - EXT / 2, FOOT[1] - EXT / 2, FOOT[2] + EXT / 2, FOOT[3] + EXT / 2], floor.base - 0.2, floor.base));
    for (const spec of floor.rooms) {
      const occurrenceId = token(block, spec.n, floor.short);
      const room = rooms.get(spec.n) ?? { roomId: id(block, spec.n), label: spec.label, atlasPlaceId: spec.place === null ? null : place(spec.place), occurrences: [] };
      room.occurrences.push({ spaceOccurrenceId: occurrenceId, floorId: floor.floorId, ifcGlobalId: spec.ifc });
      rooms.set(spec.n, room);
      if (!spec.rect) continue;
      features.push({ occurrenceId, role: 'space', rings: [ring(spec.rect)] });
      if (spec.mesh !== 'none') add(floor.floorId, spec.mesh === 'bound' ? occurrenceId : null, box(spec.rect, floor.base, floor.base + 0.02));
    }
    for (const rect of wallRects(floor.walls)) {
      features.push({ occurrenceId: null, role: 'wall', rings: [ring(rect)] });
      add(floor.floorId, null, box(rect, floor.base, floor.base + 2.6));
    }
    for (const rect of floor.openings) features.push({ occurrenceId: null, role: 'opening', rings: [ring(rect)] });
    return { floorId: floor.floorId, label: floor.label, short: floor.short, ifcStoreyGlobalId: null, elevation: null, plan: { features } };
  });
  return { floors: presentationFloors, rooms: [...rooms.values(), ...extraRooms], meshes };
}

const coordinates: CoordinateFacts = {
  renderer: { units: 'm', upAxis: 'Y' },
  source: { units: 'mm', upAxis: 'Z', basis: 'converter-declaration' },
  converters: [{ floorId: null, name: 'Synthetic converter declaration', version: 'fixture', configSha256: placeholderDigest(0x0c) }],
  physicalAlignment: 'unknown',
};

const artifacts = (base: number, floorIds: readonly string[]): ArtifactPin[] => [
  { label: 'publication.json', floorId: null, sha256: placeholderDigest(base), bytes: null },
  { label: 'semantics.json', floorId: null, sha256: placeholderDigest(base + 1), bytes: null },
  ...floorIds.flatMap((floorId, i) => [
    { label: 'model.glb', floorId, sha256: placeholderDigest(base + 2 + i * 2), bytes: null },
    { label: 'floorplan.json', floorId, sha256: placeholderDigest(base + 3 + i * 2), bytes: null },
  ]),
];

function pin(fields: Pick<PublicationPin, 'publicationId' | 'sourceRevisionId' | 'semanticMapRevision' | 'selection' | 'publishedAt' | 'sourceDate' | 'retrievedAt' | 'owner' | 'artifacts'>): PublicationPin {
  return { sourceRevisionSha256: null, sourceIfcSha256: null, semanticMapSha256: null, validation: null, ...fields };
}

function overlays(prefix: string, publicationId: string, includeDining: boolean): OverlayLayer[] {
  return [
    { id: `${prefix}-electrical`, publicationId, label: 'Synthetic electrical', tone: 'electrical', owner: 'Synthetic circuit fixture',
      sourceDate: '2026-09-30', retrievedAt: '2026-10-15T08:10:00Z', freshness: 'current', records: [
        { id: `${prefix}-e1`, label: 'Circuit 3, sockets', atlasPlaceId: place(2), detail: 'Breaker 3, 16 A' },
        { id: `${prefix}-e2`, label: 'Circuit 4, cooker', atlasPlaceId: place(2), detail: 'Breaker 4, 32 A' },
        { id: `${prefix}-e3`, label: 'Circuit 1, lighting', atlasPlaceId: place(1), detail: null },
        { id: `${prefix}-e4`, label: 'Circuit 5, utility', atlasPlaceId: place(5), detail: 'Breaker 5, 20 A' },
        ...(includeDining ? [{ id: `${prefix}-e5`, label: 'Circuit 6, dining', atlasPlaceId: place(7), detail: null }] : []),
        { id: `${prefix}-e6`, label: 'Circuit 7, outside light', atlasPlaceId: null, detail: 'No room link' },
        { id: `${prefix}-e7`, label: 'Circuit 8, removed shed', atlasPlaceId: place(99), detail: 'Place not in this publication' },
      ] },
    { id: `${prefix}-network`, publicationId, label: 'Synthetic network', tone: 'network', owner: 'Synthetic network fixture',
      sourceDate: null, retrievedAt: '2026-10-14T21:40:00Z', freshness: 'stale', records: [
        { id: `${prefix}-n1`, label: 'Access point', atlasPlaceId: place(3), detail: 'Position in room unknown' },
        { id: `${prefix}-n2`, label: 'Router', atlasPlaceId: place(6), detail: 'Position in room unknown' },
      ] },
    // Pinned to another publication: the viewer must withhold it.
    { id: `${prefix}-water-other`, publicationId: 'synthetic-publication-other', label: 'Synthetic water', tone: 'water', owner: 'Synthetic water fixture',
      sourceDate: null, retrievedAt: null, freshness: 'unknown', records: [
        { id: `${prefix}-w1`, label: 'Stopcock', atlasPlaceId: place(5), detail: null },
      ] },
  ];
}

const groundFloor = (rooms: RoomSpec[]): FloorSpec => ({ floorId: GROUND, label: 'Synthetic ground floor', short: 'G', base: 0, rooms, walls: groundWalls,
  openings: [[4.6, 8.5 - EXT / 2, 5.6, 8.5 + EXT / 2]] });

/** Publication A: single floor, publisher-shaped, published. */
export function publicationA(): CanonicalPresentation {
  const built = build('c1a', [groundFloor(groundRooms('Kitchen', true))], []);
  return {
    kind: PRESENTATION_KIND, origin: { kind: 'synthetic-fixture', coverage: 'publisher-shaped' },
    publication: pin({ publicationId: 'synthetic-publication-a', sourceRevisionId: 'synthetic-ifc-revision-1', semanticMapRevision: 'synthetic-semantic-map-1',
      selection: { mode: 'published', revision: null }, publishedAt: '2026-10-15T09:00:00Z', sourceDate: '2026-10-01', retrievedAt: '2026-10-15T09:05:00Z',
      owner: 'Synthetic HouseAtlas publisher fixture', artifacts: artifacts(0xa0, [GROUND]) }),
    coordinates, registration: { kind: 'isolated-floors' },
    building: { buildingId: BUILDING_A, label: 'Synthetic house, publication fixture', scope: SCOPE },
    floors: built.floors, rooms: built.rooms, meshes: built.meshes, overlays: overlays('a', 'synthetic-publication-a', true),
  };
}

/** Publication B: next immutable revision. The kitchen is renamed (same room
 * and occurrence); the dining room is removed and a new garden room takes its
 * area (new room, new occurrence, no reviewed Atlas link yet). */
export function publicationB(): CanonicalPresentation {
  const built = build('c1a', [groundFloor(groundRooms('Kitchen and dining', false))], []);
  return {
    kind: PRESENTATION_KIND, origin: { kind: 'synthetic-fixture', coverage: 'publisher-shaped' },
    publication: pin({ publicationId: 'synthetic-publication-b', sourceRevisionId: 'synthetic-ifc-revision-2', semanticMapRevision: 'synthetic-semantic-map-2',
      selection: { mode: 'preview', revision: 'synthetic-preview-2' }, publishedAt: null, sourceDate: '2026-10-12', retrievedAt: '2026-10-15T09:20:00Z',
      owner: 'Synthetic HouseAtlas publisher fixture', artifacts: artifacts(0xb0, [GROUND]) }),
    coordinates, registration: { kind: 'isolated-floors' },
    building: { buildingId: BUILDING_A, label: 'Synthetic house, publication fixture', scope: SCOPE },
    floors: built.floors, rooms: built.rooms, meshes: built.meshes, overlays: overlays('b', 'synthetic-publication-b', false),
  };
}

/** Generated two-floor presentation coverage in one declared frame. Not
 * publisher output. The stair hall is one logical room with an occurrence on
 * each floor; two distinct rooms share the label "Bedroom". The upper floor
 * height is invented here. */
export function generatedCoverage(): CanonicalPresentation {
  const upper: RoomSpec[] = [
    { n: 11, label: 'Bedroom', rect: [0, 0, 5.0, 4.2], mesh: 'bound', ifc: null, place: 11 },
    { n: 12, label: 'Bedroom', rect: [5.0, 0, 11, 4.2], mesh: 'bound', ifc: null, place: 12 },
    { n: 13, label: 'Box room', rect: [0, 4.2, 3.6, 8.5], mesh: 'display-only', ifc: null, place: null },
    { n: 3, label: 'Stair hall', rect: [3.6, 4.2, 6.4, 8.5], mesh: 'bound', ifc: null, place: 3 },
    { n: 15, label: 'Bathroom', rect: [6.4, 4.2, 11, 6.4], mesh: 'bound', ifc: null, place: null },
    // Plan only: a shape with no mesh.
    { n: 16, label: 'Linen store', rect: [6.4, 6.4, 11, 8.5], mesh: 'none', ifc: null, place: null },
  ];
  const built = build('c2a', [
    { ...groundFloor(groundRooms('Kitchen', true)), floorId: COVERAGE_GROUND },
    { floorId: UPPER, label: 'Synthetic upper floor', short: '1', base: 2.9, rooms: upper, walls: upperWalls, openings: [] },
  ], [{ roomId: id('c2a', 300), label: 'Loft', atlasPlaceId: null, occurrences: [{ spaceOccurrenceId: 'synthetic space c2a/300 @ floor unknown', floorId: null, ifcGlobalId: null }] }]);
  return {
    kind: PRESENTATION_KIND, origin: { kind: 'synthetic-fixture', coverage: 'generated-presentation-coverage' },
    publication: pin({ publicationId: 'synthetic-coverage-two-floors', sourceRevisionId: 'synthetic-generated-coverage', semanticMapRevision: 'synthetic-generated-coverage',
      selection: { mode: 'preview', revision: null }, publishedAt: null, sourceDate: null, retrievedAt: null, owner: 'Generated presentation coverage',
      artifacts: artifacts(0xc0, [COVERAGE_GROUND, UPPER]) }),
    coordinates: { ...coordinates, source: { units: 'unknown', upAxis: 'unknown', basis: 'unknown' }, converters: [] },
    registration: { kind: 'shared-frame', basis: 'Generated coverage frame' },
    building: { buildingId: BUILDING_COVERAGE, label: 'Synthetic house, generated two-floor coverage', scope: SCOPE },
    floors: built.floors, rooms: built.rooms, meshes: built.meshes, overlays: overlays('c', 'synthetic-coverage-two-floors', true),
  };
}

export const SYNTHETIC_FIXTURES = {
  a: { label: 'Publication A, one floor', make: publicationA },
  b: { label: 'Publication B, next revision', make: publicationB },
  coverage: { label: 'Generated two-floor coverage', make: generatedCoverage },
} as const;
export type SyntheticFixtureKey = keyof typeof SYNTHETIC_FIXTURES;
